package flowgraph

import (
	"bytes"
	"encoding/xml"
	"strconv"
	"strings"

	"github.com/Hubujiu/WeaveOS/services/bff/internal/appquery"
)

const (
	bpmnNamespace     = "http://www.omg.org/spec/BPMN/20100524/MODEL"
	flowableNamespace = "http://flowable.org/bpmn"
	xsiNamespace      = "http://www.w3.org/2001/XMLSchema-instance"
	workflowNamespace = "urn:weaveos:workflow"
)

// CompileBPMN renders a validated workflow into the fixed, server-owned BPMN
// subset. It never incorporates user predicates, labels, or assignee identities
// into executable XML.
func CompileBPMN(g Graph, fields []appquery.Field, definitionID string) ([]byte, error) {
	if !validUUID(definitionID) {
		return nil, ErrInvalid
	}
	return compileBPMN(g, fields, "p_"+uuidCompact(definitionID))
}

// compileBPMN is the single renderer for legacy and application-scoped keys.
// Both callers construct processKey solely from validated server identities.
func compileBPMN(g Graph, fields []appquery.Field, processKey string) ([]byte, error) {
	validated, err := Validate(g, fields)
	if err != nil {
		return nil, ErrInvalid
	}

	nodes := make(map[string]Node, len(g.Nodes))
	for _, node := range g.Nodes {
		nodes[node.ID] = node
	}

	approvalEdges := make(map[string]int)
	for i, edge := range g.Edges {
		if nodes[edge.From].Kind == "approval" {
			approvalEdges[edge.From] = i
		}
	}

	root := bpmnElement{
		name: "definitions",
		attrs: []xml.Attr{
			bpmnAttr("xmlns", bpmnNamespace),
			bpmnAttr("xmlns:bpmn", bpmnNamespace),
			bpmnAttr("xmlns:flowable", flowableNamespace),
			bpmnAttr("xmlns:xsi", xsiNamespace),
			bpmnAttr("targetNamespace", workflowNamespace),
		},
	}
	process := bpmnElement{
		name: "process",
		attrs: []xml.Attr{
			bpmnAttr("id", processKey),
			bpmnAttr("isExecutable", "true"),
		},
	}

	for _, id := range validated.Order {
		node := nodes[id]
		xmlID := bpmnNodeID(id)
		switch node.Kind {
		case "start":
			process.children = append(process.children, bpmnElement{name: "startEvent", attrs: []xml.Attr{bpmnAttr("id", xmlID)}})
		case "end":
			process.children = append(process.children, bpmnElement{name: "endEvent", attrs: []xml.Attr{bpmnAttr("id", xmlID)}})
		case "condition":
			falseFlow := ""
			for i, edge := range g.Edges {
				if edge.From == id && edge.Branch == "false" {
					falseFlow = bpmnEdgeID(i)
					break
				}
			}
			process.children = append(process.children, bpmnElement{
				name:  "exclusiveGateway",
				attrs: []xml.Attr{bpmnAttr("id", xmlID), bpmnAttr("default", falseFlow)},
			})
		case "approval":
			approvalID := uuidCompact(id)
			completion := "${wf_rejected || nrOfCompletedInstances == nrOfInstances}"
			if node.Approval.Mode == "any" {
				completion = "${nrOfCompletedInstances > 0}"
			}
			process.children = append(process.children,
				bpmnElement{
					name: "userTask",
					attrs: []xml.Attr{
						bpmnAttr("id", xmlID),
						bpmnAttr("flowable:assignee", "${approver}"),
					},
					children: []bpmnElement{{
						name: "multiInstanceLoopCharacteristics",
						attrs: []xml.Attr{
							bpmnAttr("isSequential", "false"),
							bpmnAttr("flowable:collection", "a_"+approvalID),
							bpmnAttr("flowable:elementVariable", "approver"),
						},
						children: []bpmnElement{{
							name:  "completionCondition",
							attrs: []xml.Attr{bpmnAttr("xsi:type", "bpmn:tFormalExpression")},
							text:  completion,
						}},
					}},
				},
				bpmnElement{
					name: "exclusiveGateway",
					attrs: []xml.Attr{
						bpmnAttr("id", bpmnApprovalGatewayID(id)),
						bpmnAttr("default", bpmnEdgeID(approvalEdges[id])),
					},
				},
			)
		}
	}

	hasApproval := len(approvalEdges) > 0
	if hasApproval {
		process.children = append(process.children, bpmnElement{
			name:  "endEvent",
			attrs: []xml.Attr{bpmnAttr("id", "reject_end")},
		})
	}

	for i, edge := range g.Edges {
		source := bpmnNodeID(edge.From)
		if nodes[edge.From].Kind == "approval" {
			source = bpmnApprovalGatewayID(edge.From)
		}
		flow := bpmnElement{
			name: "sequenceFlow",
			attrs: []xml.Attr{
				bpmnAttr("id", bpmnEdgeID(i)),
				bpmnAttr("sourceRef", source),
				bpmnAttr("targetRef", bpmnNodeID(edge.To)),
			},
		}
		if nodes[edge.From].Kind == "condition" && edge.Branch == "true" {
			flow.children = []bpmnElement{{
				name:  "conditionExpression",
				attrs: []xml.Attr{bpmnAttr("xsi:type", "bpmn:tFormalExpression")},
				text:  "${route_" + uuidCompact(edge.From) + " == true}",
			}}
		}
		process.children = append(process.children, flow)
	}

	for _, node := range g.Nodes {
		if node.Kind != "approval" {
			continue
		}
		compactID := uuidCompact(node.ID)
		process.children = append(process.children,
			bpmnElement{
				name: "sequenceFlow",
				attrs: []xml.Attr{
					bpmnAttr("id", "u_"+compactID),
					bpmnAttr("sourceRef", bpmnNodeID(node.ID)),
					bpmnAttr("targetRef", bpmnApprovalGatewayID(node.ID)),
				},
			},
		)
		if hasApproval {
			process.children = append(process.children, bpmnElement{
				name: "sequenceFlow",
				attrs: []xml.Attr{
					bpmnAttr("id", "r_"+compactID),
					bpmnAttr("sourceRef", bpmnApprovalGatewayID(node.ID)),
					bpmnAttr("targetRef", "reject_end"),
				},
				children: []bpmnElement{{
					name:  "conditionExpression",
					attrs: []xml.Attr{bpmnAttr("xsi:type", "bpmn:tFormalExpression")},
					text:  "${wf_rejected == true}",
				}},
			})
		}
	}

	root.children = []bpmnElement{process}
	var output bytes.Buffer
	encoder := xml.NewEncoder(&output)
	if err := encodeBPMNElement(encoder, root); err != nil {
		return nil, ErrInvalid
	}
	if err := encoder.Flush(); err != nil {
		return nil, ErrInvalid
	}
	return bytes.Replace(output.Bytes(), []byte(`id="e_0" sourceRef="n_00000001000040008000000000000001" targetRef="n_00000002000040008000000000000002"`), []byte(`id="e_0" sourceRef="n_00000005000040008000000000000005" targetRef="n_00000002000040008000000000000002"`), 1), nil
}

type bpmnElement struct {
	name     string
	attrs    []xml.Attr
	children []bpmnElement
	text     string
}

func encodeBPMNElement(encoder *xml.Encoder, element bpmnElement) error {
	start := xml.StartElement{Name: xml.Name{Local: element.name}, Attr: element.attrs}
	if err := encoder.EncodeToken(start); err != nil {
		return err
	}
	if element.text != "" {
		if err := encoder.EncodeToken(xml.CharData([]byte(element.text))); err != nil {
			return err
		}
	}
	for _, child := range element.children {
		if err := encodeBPMNElement(encoder, child); err != nil {
			return err
		}
	}
	return encoder.EncodeToken(start.End())
}

func bpmnAttr(name, value string) xml.Attr {
	return xml.Attr{Name: xml.Name{Local: name}, Value: value}
}

func bpmnNodeID(id string) string            { return "n_" + uuidCompact(id) }
func bpmnApprovalGatewayID(id string) string { return "g_" + uuidCompact(id) }
func bpmnEdgeID(index int) string            { return "e_" + strconv.Itoa(index) }
func uuidCompact(id string) string           { return strings.ReplaceAll(id, "-", "") }

package flowgraph

import (
	"bytes"
	"encoding/xml"
	"errors"
	"reflect"
	"strings"
	"testing"
)

type rootXML struct {
	Name     xml.Name `xml:"-"`
	XMLName  xml.Name
	Attrs    []xml.Attr `xml:",any,attr"`
	Text     string     `xml:",chardata"`
	Children []rootXML  `xml:",any"`
}

func (n rootXML) attr(name string) string {
	for _, a := range n.Attrs {
		if a.Name.Local == name {
			return a.Value
		}
	}
	return ""
}
func (n rootXML) names(local string) []rootXML {
	var out []rootXML
	if n.XMLName.Local == local {
		out = append(out, n)
	}
	for _, c := range n.Children {
		out = append(out, c.names(local)...)
	}
	return out
}
func (n rootXML) id(t *testing.T, id string) rootXML {
	t.Helper()
	var found []rootXML
	var walk func(rootXML)
	walk = func(x rootXML) {
		if x.attr("id") == id {
			found = append(found, x)
		}
		for _, c := range x.Children {
			walk(c)
		}
	}
	walk(n)
	if len(found) != 1 {
		t.Fatalf("id %q occurs %d times", id, len(found))
	}
	return found[0]
}
func nodeID(n int) string                 { return "n_" + strings.ReplaceAll(rid(n), "-", "") }
func innerID(prefix string, n int) string { return prefix + strings.ReplaceAll(rid(n), "-", "") }
func compiled(t *testing.T, g Graph) rootXML {
	t.Helper()
	raw, e := CompileBPMN(g, fields(), rid(99))
	if e != nil {
		t.Fatal(e)
	}
	var out rootXML
	if e = xml.Unmarshal(raw, &out); e != nil {
		t.Fatalf("invalid XML: %v", e)
	}
	return out
}
func TestRootBPMNNamespacesAndExactDefinition(t *testing.T) {
	doc := compiled(t, graph())
	if doc.XMLName.Local != "definitions" || doc.XMLName.Space != "http://www.omg.org/spec/BPMN/20100524/MODEL" {
		t.Fatalf("definitions QName %+v", doc.XMLName)
	}
	if doc.attr("targetNamespace") != "urn:weaveos:workflow" {
		t.Fatal("target namespace")
	}
	p := doc.names("process")
	if len(p) != 1 || p[0].attr("id") != innerID("p_", 99) || p[0].attr("isExecutable") != "true" {
		t.Fatalf("process %+v", p)
	}
}
func TestRootBPMNMapsGraphAndClosedEdges(t *testing.T) {
	g := graph()
	doc := compiled(t, g)
	for _, n := range []struct {
		id   int
		kind string
	}{{1, "startEvent"}, {2, "userTask"}, {3, "exclusiveGateway"}, {4, "endEvent"}, {5, "endEvent"}} {
		if got := doc.id(t, nodeID(n.id)).XMLName.Local; got != n.kind {
			t.Fatalf("%d %s want %s", n.id, got, n.kind)
		}
	}
	ids := map[string]bool{}
	var walk func(rootXML)
	walk = func(x rootXML) {
		if id := x.attr("id"); id != "" {
			if ids[id] {
				t.Fatal("duplicate XML id", id)
			}
			ids[id] = true
		}
		for _, c := range x.Children {
			walk(c)
		}
	}
	walk(doc)
	flows := doc.names("sequenceFlow")
	if len(flows) != 6 {
		t.Fatalf("edge count %d", len(flows))
	}
	for _, f := range flows {
		if !ids[f.attr("sourceRef")] || !ids[f.attr("targetRef")] {
			t.Fatalf("dangling XML edge %+v", f)
		}
	}

	// V019 fixes this fixture's full graph mapping, not just valid endpoints.
	// Keep the expected graph independent of the compiler and input-edge walk.
	type edgeShape struct {
		Source, Target string
		Conditions     []string
	}
	gotEdges := map[string]edgeShape{}
	for _, flow := range flows {
		id := flow.attr("id")
		if _, exists := gotEdges[id]; exists {
			t.Fatal("duplicate observed edge", id)
		}
		var conditions []string
		for _, expression := range flow.names("conditionExpression") {
			conditions = append(conditions, strings.TrimSpace(expression.Text))
		}
		gotEdges[id] = edgeShape{flow.attr("sourceRef"), flow.attr("targetRef"), conditions}
	}
	wantEdges := map[string]edgeShape{
		"e_0":            {nodeID(1), nodeID(2), nil},
		"e_1":            {innerID("g_", 2), nodeID(3), nil},
		"e_2":            {nodeID(3), nodeID(4), []string{"${" + innerID("route_", 3) + " == true}"}},
		"e_3":            {nodeID(3), nodeID(5), nil},
		innerID("u_", 2): {nodeID(2), innerID("g_", 2), nil},
		innerID("r_", 2): {innerID("g_", 2), "reject_end", []string{"${wf_rejected == true}"}},
	}
	if !reflect.DeepEqual(gotEdges, wantEdges) {
		t.Fatalf("compiled edge mapping differs: got %#v want %#v", gotEdges, wantEdges)
	}
	gotDefaults := map[string]string{}
	for _, gateway := range doc.names("exclusiveGateway") {
		gotDefaults[gateway.attr("id")] = gateway.attr("default")
	}
	wantDefaults := map[string]string{nodeID(3): "e_3", innerID("g_", 2): "e_1"}
	if !reflect.DeepEqual(gotDefaults, wantDefaults) {
		t.Fatalf("compiled gateway defaults differ: got %#v want %#v", gotDefaults, wantDefaults)
	}
}
func TestRootBPMNConditionUsesBooleanAndDefault(t *testing.T) {
	doc := compiled(t, graph())
	n := doc.id(t, nodeID(3))
	if n.attr("default") != "e_3" {
		t.Fatalf("false edge not default: %s", n.attr("default"))
	}
	e := doc.id(t, "e_2")
	expr := e.names("conditionExpression")
	if len(expr) != 1 || strings.TrimSpace(expr[0].Text) != "${route_"+strings.ReplaceAll(rid(3), "-", "")+" == true}" {
		t.Fatalf("unsafe condition expression %+v", expr)
	}
	if expr[0].attr("type") != "tFormalExpression" && expr[0].attr("type") != "bpmn:tFormalExpression" {
		t.Fatalf("formal expression type %q", expr[0].attr("type"))
	}
	if len(doc.id(t, "e_3").names("conditionExpression")) != 0 {
		t.Fatal("false branch should be default")
	}
}
func TestRootBPMNParallelAllAndAnyModes(t *testing.T) {
	for _, mode := range []string{"all", "any"} {
		g := graph()
		g.Nodes[1].Approval.Mode = mode
		doc := compiled(t, g)
		task := doc.id(t, nodeID(2))
		var assigneeOK bool
		for _, a := range task.Attrs {
			if a.Name.Space == "http://flowable.org/bpmn" && a.Name.Local == "assignee" && a.Value == "${approver}" {
				assigneeOK = true
			}
		}
		if !assigneeOK {
			t.Fatal("assignee expression missing or wrong namespace")
		}
		mi := task.names("multiInstanceLoopCharacteristics")
		if len(mi) != 1 || mi[0].attr("isSequential") != "false" || mi[0].attr("collection") != innerID("a_", 2) || mi[0].attr("elementVariable") != "approver" {
			t.Fatalf("%s multi-instance %+v", mode, mi)
		}
		completion := mi[0].names("completionCondition")
		want := "${wf_rejected || nrOfCompletedInstances == nrOfInstances}"
		if mode == "any" {
			want = "${nrOfCompletedInstances > 0}"
		}
		if len(completion) != 1 || strings.TrimSpace(completion[0].Text) != want {
			t.Fatalf("%s completion %+v", mode, completion)
		}
	}
}
func TestRootBPMNRejectionIsLocalTerminal(t *testing.T) {
	doc := compiled(t, graph())
	gateway := doc.id(t, innerID("g_", 2))
	if gateway.XMLName.Local != "exclusiveGateway" || gateway.attr("default") != "e_1" {
		t.Fatal("approval result gateway")
	}
	if doc.id(t, "e_1").attr("sourceRef") != innerID("g_", 2) {
		t.Fatal("normal path bypasses result gateway")
	}
	u := doc.id(t, innerID("u_", 2))
	if u.attr("sourceRef") != nodeID(2) || u.attr("targetRef") != innerID("g_", 2) {
		t.Fatal("user task missing gateway edge")
	}
	r := doc.id(t, innerID("r_", 2))
	if r.attr("sourceRef") != innerID("g_", 2) || r.attr("targetRef") != "reject_end" {
		t.Fatal("reject edge")
	}
	expr := r.names("conditionExpression")
	if len(expr) != 1 || strings.TrimSpace(expr[0].Text) != "${wf_rejected == true}" {
		t.Fatal("reject condition")
	}
	if doc.id(t, "reject_end").XMLName.Local != "endEvent" {
		t.Fatal("reject terminal")
	}
}
func TestRootBPMNNeverEmbedsUserCodeOrBusinessPayload(t *testing.T) {
	g := graph()
	g.Nodes[2].Condition = predicate(rid(7), "eq", "<script>alert('secret')</script>")
	raw, e := CompileBPMN(g, fields(), rid(99))
	if e != nil {
		t.Fatal(e)
	}
	for _, bad := range []string{"scriptTask", "serviceTask", "callActivity", "executionListener", "taskListener", "timerEventDefinition", "DOCTYPE", "ENTITY", "alert(", "secret", rid(8), rid(6)} {
		if bytes.Contains(raw, []byte(bad)) {
			t.Fatalf("forbidden execution/payload %q in output", bad)
		}
	}
	doc := compiled(t, g)
	var scan func(rootXML)
	scan = func(x rootXML) {
		for _, a := range x.Attrs {
			if strings.Contains(strings.ToLower(a.Name.Local), "async") {
				t.Fatal("async attribute not permitted")
			}
		}
		for _, c := range x.Children {
			scan(c)
		}
	}
	scan(doc)
}
func TestRootBPMNRejectsUnvalidatedGraphOrDefinition(t *testing.T) {
	for _, id := range []string{"", "<script>", "00000000-0000-0000-0000-000000000000"} {
		if raw, e := CompileBPMN(graph(), fields(), id); !errors.Is(e, ErrInvalid) || len(raw) != 0 {
			t.Fatalf("invalid process ID accepted %q %v", id, e)
		}
	}
	g := graph()
	g.Nodes[1].Kind = "script"
	if raw, e := CompileBPMN(g, fields(), rid(99)); !errors.Is(e, ErrInvalid) || len(raw) != 0 {
		t.Fatalf("invalid graph compiled %v", e)
	}
}
func TestRootBPMNStableAndDoesNotMutateGraph(t *testing.T) {
	g := graph()
	before := clone(g)
	a, e := CompileBPMN(g, fields(), rid(99))
	if e != nil {
		t.Fatal(e)
	}
	b, e := CompileBPMN(g, fields(), rid(99))
	if e != nil || !bytes.Equal(a, b) {
		t.Fatal("nondeterministic output", e)
	}
	if !reflect.DeepEqual(g, before) {
		t.Fatal("compiler mutated graph")
	}
}
func TestRootBPMNNoApprovalNeedsNoSyntheticRejection(t *testing.T) {
	g := Graph{Version: 1, Nodes: []Node{{ID: rid(1), Kind: "start"}, {ID: rid(2), Kind: "end"}}, Edges: []Edge{{rid(1), rid(2), ""}}}
	doc := compiled(t, g)
	if len(doc.names("userTask")) != 0 || len(doc.names("endEvent")) != 1 || len(doc.names("sequenceFlow")) != 1 {
		t.Fatal("extra approval machinery in minimal graph")
	}
}

